 const p1=`${label}: ${stageTxt}. ${v251Planet(z.md,lang)} Mahadasha sets the larger life background while ${v251Planet(z.ad,lang)} Bhukti brings the nearer active area forward${pnames.length?`; priorities are ${pnames.join('; ')}`:''}.`;
 let p2;if(age<=15){const eb=stage==='primary'?ed?.bands?.primary:stage==='secondary'?ed?.bands?.secondary:ed?.bands?.foundation||'mixed';p2=`For ${label}, age-stage priorities come first. Education capacity is ${v252BandLabel(eb,lang)}; mother/home support is ${v252BandLabel(sp?.bands?.mother||'mixed',lang)}, father/guidance ${v252BandLabel(sp?.bands?.father||'mixed',lang)}, mental receptivity ${v252BandLabel(hp?.bands?.mental||'mixed',lang)} and sleep/rest ${v252BandLabel(hp?.bands?.rest||'mixed',lang)}.`}else{const focus=pnames[0]||stageTxt,forms=[`For ${label}, ${focus} is the first present-life test; the wider ${stageTxt} background is read only through changes that actually appear in the current context.`,`In ${label}, start with ${focus} and then connect only the parts of the ${stageTxt} background that are active in real life; do not force every adult significator into one period.`,`Judge ${label} first by whether ${focus} changes in lived experience; the rest of the ${stageTxt} background remains secondary unless a real event activates it.`,`The practical gate for ${label} is ${focus}. Only the parts of the ${stageTxt} background that fit current work, family and residence context are brought forward.`];p2=forms[idx%forms.length]};
 const p3=trs.length?`${label} transit cross-check: ${trs.map(t=>`${v251Planet(t.planet,lang)} activates house ${num(t.house)} during ${text(t.start)}–${text(t.end)}, modifying pace/load around ${pickLang(t.meaning,lang)}`).join('; ')}. Transit does not create a new destiny outside the Dasha/natal promise.`:`There is no distinct slow-transit change inside ${label}, so the Dasha promise remains the main timing base.`;
 const p4=wins.length?`Change-points inside ${label}: ${wins.map(w=>`${text(w.start)}–${text(w.end)}: ${pickLang(w.primary,lang)}${pickLang(w.secondary,lang)?`; then ${pickLang(w.secondary,lang)}`:''}`).join('; ')}. Confirm these dates through real age-appropriate events.`:`Judge ${label} through real age-appropriate change rather than dates alone.`;
 return {title:`${label} · ${v251Planet(z.md,lang)}–${v251Planet(z.ad,lang)}`,paragraphs:[p1,p2,p3,p4]};
