function yearsAt(dateStr,whenStr){
 const b=new Date(String(dateStr||'')+'T00:00:00Z'),d=new Date(String(whenStr||'')+'T00:00:00Z');if(!Number.isFinite(+b)||!Number.isFinite(+d))return null;let y=d.getUTCFullYear()-b.getUTCFullYear();const md=(d.getUTCMonth()-b.getUTCMonth())*100+(d.getUTCDate()-b.getUTCDate());if(md<0)y--;return y;
}
function matchingAgeNote(e,lang){
 const d=text(e?.referenceDate)||new Date().toISOString().slice(0,10),ba=yearsAt(e?.brideBirthDate,d),ga=yearsAt(e?.groomBirthDate,d);
 if(lang==='ta')return `வயது சூழல்: பெண் ${ba==null?'—':ba}, ஆண் ${ga==null?'—':ga}. வயது வந்த நிலையுக்கு முன் உள்ள காலங்களை திருமணம்/தாம்பத்யம் என்று நேரடியாக வாசிக்காமல், கல்வி, குடும்ப சூழல், உணர்ச்சி முதிர்ச்சி மற்றும் எதிர்கால உறவு தயார் நிலையாக மாற்றப்படுகிறது.`;
 return `Age context: Bride ${ba==null?'—':ba}, Groom ${ga==null?'—':ga}. Periods before adulthood are not read as current marriage/intimacy events; they are translated into study, family environment, emotional maturity and future relationship readiness.`;
}
