function v253Phase(z,e,lang){
 const ta=lang==='ta',p=arr(z.priorities),title=`${z.start} → ${z.end} · ${v251Planet(z.md,lang)}–${v251Planet(z.ad,lang)}`;
 const md=arr(e.houses).find(h=>arr(h.occupants).includes(z.md)),ad=arr(e.houses).find(h=>arr(h.occupants).includes(z.ad));
 const intro=md&&ad?(ta?`${v251Planet(z.md,lang)} தசை, ${v251Planet(z.ad,lang)} புக்தி நடைபெறும் இந்தக் கட்டத்தில் பிறப்பு ஜாதகத்தின் ${md.house} மற்றும் ${ad.house}-ஆம் பாவத் தொடர்புகள் காலப் பலனில் பங்கு பெறுகின்றன.`:`During this ${v251Planet(z.md,lang)}–${v251Planet(z.ad,lang)} period, the natal placements in houses ${md.house} and ${ad.house} contribute to the timing assessment.`):'';
 const sections=[{title:ta?'இந்தக் காலத்தின் ஜாதகப் பின்னணி':'Chart background for this period',paragraphs:[intro]}];
 const mdOwned=arr(v259Position(e,z.md)?.ownedHouses).filter(v259ValidHouse),adOwned=arr(v259Position(e,z.ad)?.ownedHouses).filter(v259ValidHouse);
 if(md||ad){const first=ta?`${v251Planet(z.md,lang)} மகாதசை${md?' பிறப்பு '+md.house+'-ஆம் பாவம்':''}${mdOwned.length?' மற்றும் '+mdOwned.join(', ')+'-ஆம் அதிபத்தியம்':''} வழியாகப் பரந்த வாழ்க்கைச் சூழலைக் காட்டுகிறது. ${v251Planet(z.ad,lang)} புக்தி${ad?' பிறப்பு '+ad.house+'-ஆம் பாவம்':''}${adOwned.length?' மற்றும் '+adOwned.join(', ')+'-ஆம் அதிபத்தியம்':''} வழியாக அதில் தற்போது முக்கியமான செயலைக் குறிக்கிறது.`:`Mahadasha ${z.md}${md?' occupies natal house '+md.house:''}${mdOwned.length?' and rules '+mdOwned.join(', '):''}, while Bhukti ${z.ad}${ad?' occupies natal house '+ad.house:''}${adOwned.length?' and rules '+adOwned.join(', '):''}. The first supplies the broader natal background and the second narrows the live question.`;
 sections.push({title:ta?'தசாநாதன்–புக்திநாதன் தொடர்பு':'Mahadasha and Bhukti lordship',paragraphs:[first]})} 
 for(const [planet,role]of [[z.md,ta?'தசாநாதன்':'Mahadasha lord'],[z.ad,ta?'புக்திநாதன்':'Bhukti lord']]){
 const house=arr(e.houses).find(h=>arr(h.occupants).includes(planet)),reading=house?.planetReadings?.[planet]?.[lang];
 if(reading&&(z.age==null||z.age>18))sections.push({title:`${role} ${v251Planet(planet,lang)}`,paragraphs:[ta?`${z.start} முதல் ${z.end} வரையிலான இந்தக் கட்டத்தில் ${role} ${v251Planet(planet,lang)} பிறப்பு ஜாதகத்தின் ${house.house}-ஆம் பாவத்தில் இருப்பதை இணைத்துப் பார்க்கிறோம். அங்கு இந்தக் கிரகம் குறிக்கும் இயல்பு: ${reading}. கீழே கூறப்படும் நிகழ்வு அல்லது பொறுப்பை அணுகும் விதத்தில் இந்தப் பின்னணி பங்கு பெறலாம்.`:`In the period from ${z.start} to ${z.end}, ${role} ${planet} occupies natal house ${house.house}. Its natal expression there is: ${reading}. This provides context for how the opportunities or responsibilities below may be approached.`]});
 }

 for(const q of p){const event=pickLang(q.event,lang);if(!event)continue;const prose=z.age!=null&&z.age<21?'':V253_EVENT_PROSE[q.eventId]?.[ta?1:0]||'';
 const state=ta?(q.state==='support'?'முன்னெடுக்க உதவும் காலச் சுட்டி உள்ளது':q.state==='pressure'?'முதலில் உள்ள சிரமத்தைச் சரிசெய்ய வேண்டிய காலம்':'வாய்ப்புடன் சில நடைமுறைச் சிக்கல்களும் கலந்து வரலாம்'):(q.state==='support'?'the period offers supporting indications':q.state==='pressure'?'the immediate emphasis is on resolving the difficulty':'opportunity and practical constraints may arrive together');
 sections.push({title:pickLang(q.title,lang),paragraphs:[`${z.start} → ${z.end} · ${event}: ${state}.`,prose]})}
 const wins=arr(e.timeline).filter(w=>w.start<=z.end&&w.end>=z.start);
 for(const w of wins){const start=w.start<z.start?z.start:w.start,end=w.end>z.end?z.end:w.end;sections.push({title:`${start} → ${end}`,paragraphs:[pickLang(w.primary,lang)?`${start} → ${end} · ${pickLang(w.primary,lang)}`:'',pickLang(w.secondary,lang)?`${start} → ${end} · ${ta?'இணைந்து கவனிக்க வேண்டியது':'Related focus'}: ${pickLang(w.secondary,lang)}`:'',pickLang(w.action,lang)?`${start} → ${end} · ${ta?'நடைமுறையில்':'In practice'}: ${pickLang(w.action,lang)}`:'']})}
 if(z.age!=null&&z.age<=18)sections.unshift({title:ta?'வயதிற்கேற்ற வாசிப்பு':'Age-appropriate context',paragraphs:[v252StageLabel(z.age,lang)]});
 return {title,...v254Sections(sections)};
}
const V253_TRANSIT={
 Jupiter:[['confidence to accept a larger role','பெரிய பொறுப்பை ஏற்கும் தன்னம்பிக்கை'],['a chance to strengthen family resources or use knowledge in speech','குடும்ப வளத்தை வளர்க்க அல்லது அறிவைப் பேச்சின் மூலம் பயன்படுத்தும் வாய்ப்பு'],['guided learning and a more constructive use of communication','வழிகாட்டலுடன் கற்றல் மற்றும் தொடர்புத் திறனைப் பயனுள்ளதாகப் பயன்படுத்துதல்'],['support for study or improving the home environment','படிப்பிற்கான ஆதரவு அல்லது வீட்டுச் சூழலை மேம்படுத்துதல்'],['room to develop an idea, teach or deepen study','கருத்தை வளர்க்க, கற்பிக்க அல்லது படிப்பை ஆழப்படுத்த இடம்'],['learning to manage duties without promising more than you can deliver','செய்யக்கூடிய அளவுக்கு வாக்குக் கொடுத்து கடமையை நிர்வகித்தல்'],['more scope for constructive agreements with partners or clients','துணைவர் அல்லது வாடிக்கையாளருடன் பயனுள்ள ஒப்பந்தத்திற்கான வாய்ப்பு'],['advice that clarifies a shared responsibility or an uncertain plan','கூட்டு பொறுப்பு அல்லது தெளிவில்லாத திட்டத்திற்கு விளக்கம் தரும் அறிவுரை'],['guidance, further learning and a wider view of your options','வழிகாட்டல், மேல்படிப்பு மற்றும் வாய்ப்புகளை விரிவாகப் புரிதல்'],['an opportunity to demonstrate professional judgement','தொழிலில் உங்கள் முடிவெடுக்கும் திறனை வெளிப்படுத்தும் வாய்ப்பு'],['help through a useful group, mentor or professional connection','பயனுள்ள குழு, வழிகாட்டி அல்லது தொழில் தொடர்பின் உதவி'],['learning away from familiar surroundings and reviewing the cost of expansion','பழகிய சூழலுக்கு வெளியே கற்றல் மற்றும் விரிவாக்கச் செலவை மறுபரிசீலனை செய்தல்']],
 Saturn:[['a need to pace personal commitments and build consistency','தனிப்பட்ட பொறுப்பை அளவாக ஏற்று தொடர்ச்சியை வளர்த்தல்'],['closer attention to family obligations and recurring expenses','குடும்பக் கடமை மற்றும் தொடர்ச்சியான செலவில் கூடுதல் கவனம்'],['steady practice even when recognition is slow','அங்கீகாரம் தாமதமானாலும் தொடர்ந்து பயிற்சி செய்தல்'],['responsibility for home, caregiving or a settled routine','வீடு, பராமரிப்பு அல்லது நிலையான வாழ்க்கை ஒழுங்கிற்கான பொறுப்பு'],['patient revision instead of judging ability by quick results','உடனடி முடிவால் திறனை மதிப்பிடாமல் பொறுமையாகத் திருத்துதல்'],['organising a heavy workload and setting limits on obligations','அதிகப் பணிச்சுமையை ஒழுங்குபடுத்தி கடமைக்கு எல்லை வகுத்தல்'],['testing whether agreements are reliable in everyday practice','ஒப்பந்தம் தினசரி வாழ்க்கையில் நம்பகமாகச் செயல்படுகிறதா எனப் பார்த்தல்'],['careful documentation and patience with shared commitments','கூட்டு பொறுப்பில் ஆவணத் தெளிவும் பொறுமையும்'],['putting principles into practice through disciplined learning','ஒழுங்கான கற்றலால் நம்பிக்கையை நடைமுறையில் பயன்படுத்துதல்'],['accountability, sustained work and a slower recognition cycle','பொறுப்புணர்வு, தொடர்ச்சியான உழைப்பு மற்றும் படிப்படியான அங்கீகாரம்'],['gains that depend on sustained contribution to a group or goal','ஒரு குழு அல்லது இலக்கிற்கான தொடர்ந்த பங்களிப்பால் வரும் பலன்'],['reducing avoidable commitments and protecting rest','தவிர்க்கக்கூடிய கடமையைக் குறைத்து ஓய்விற்கான நேரத்தைப் பாதுகாத்தல்']],
 Rahu:[['a wish to change how you present yourself','உங்களை வெளிப்படுத்தும் முறையை மாற்றும் விருப்பம்'],['unfamiliar earning ideas that need clear terms','நிபந்தனைகளைத் தெளிவுபடுத்த வேண்டிய புதிய வருமான யோசனை'],['experimentation with media, tools or communication','ஊடகம், கருவி அல்லது தொடர்பு முறையில் புதிய முயற்சி'],['a desire for a different home environment','வேறுபட்ட வீட்டுச் சூழலுக்கான விருப்பம்'],['intense interest in a new idea that needs patient verification','பொறுமையாகச் சரிபார்க்க வேண்டிய புதிய கருத்தில் தீவிர ஆர்வம்'],['unconventional ways of tackling competition and workload','போட்டி மற்றும் பணிச்சுமையை மாறுபட்ட முறையில் கையாளுதல்'],['unfamiliar partners or offers that require clear expectations','எதிர்பார்ப்பைத் தெளிவுபடுத்த வேண்டிய புதிய கூட்டாளி அல்லது வாய்ப்பு'],['curiosity about hidden details without assuming rumours are facts','வதந்தியை உண்மை என ஏற்காமல் மறைந்த விவரங்களை அறியும் ஆர்வம்'],['questioning familiar beliefs and exploring other approaches','பழகிய நம்பிக்கையை ஆராய்ந்து வேறு அணுகுமுறைகளைப் பார்த்தல்'],['ambition for a more visible or unusual professional role','வெளிப்படையான அல்லது வழக்கத்திற்கு மாறான தொழில் நிலைக்கான ஆசை'],['a wider network whose promises need verification','வாக்குறுதிகளைச் சரிபார்க்க வேண்டிய விரிவான தொடர்பு வட்டம்'],['distant opportunities whose practical cost must be understood','நடைமுறைச் செலவைப் புரிந்துகொள்ள வேண்டிய தொலைதூர வாய்ப்பு']],
 Ketu:[['reconsidering an identity that no longer feels useful','இனி பொருந்தாத தனிப்பட்ட அடையாளத்தை மறுபரிசீலனை செய்தல்'],['simplifying wants while staying engaged with family','தேவையைக் குறைத்தாலும் குடும்பத் தொடர்பைப் பேணுதல்'],['focused independent practice rather than constant outward activity','வெளிப்புறச் செயல்பாட்டை விட கவனமான தனிப் பயிற்சி'],['a need for quiet without withdrawing from home responsibilities','வீட்டுப் பொறுப்பிலிருந்து விலகாமல் அமைதிக்கான நேரம் தேடுதல்'],['depth in study without losing interest in practical expression','நடைமுறைப் பயன்பாட்டை மறக்காமல் படிப்பில் ஆழம் பெறுதல்'],['removing ineffective routines while keeping necessary duties','தேவையான கடமையைப் பேணி பயனற்ற பழக்கத்தை நீக்குதல்'],['space to examine expectations without neglecting a partner','துணையைப் புறக்கணிக்காமல் எதிர்பார்ப்பை ஆராய இடம்'],['careful investigation and release of an unworkable commitment','கவனமான ஆய்வு மற்றும் பொருந்தாத பொறுப்பிலிருந்து விடுபடுதல்'],['a more personal understanding of belief and guidance','நம்பிக்கை மற்றும் வழிகாட்டலைத் தனிப்பட்ட முறையில் புரிதல்'],['reviewing whether professional recognition still matches your purpose','தொழில் அங்கீகாரம் உங்கள் நோக்கத்துடன் பொருந்துகிறதா எனப் பார்த்தல்'],['choosing a smaller circle or fewer goals with greater meaning','பொருள் உள்ள சிறிய தொடர்பு வட்டம் அல்லது குறைந்த இலக்கைத் தேர்ந்தெடுத்தல்'],['quiet reflection and closure of unfinished commitments','அமைதியான சிந்தனை மற்றும் முடிக்காத பொறுப்பை முடித்தல்']]
};
function v253Transit(z,lang,e){
 const ta=lang==='ta',n=Number(z.house),age=z.age,planet=text(z.planet),label=v251Planet(planet,lang),v=V253_TRANSIT[planet]?.[n-1];
 if(!v259ValidHouse(n)||!planet)return '';
 const meaning=age!=null&&age<=18?pickLang(z.meaning,lang):v?.[ta?1:0]||pickLang(z.meaning,lang);
 const natal=arr(e?.houses).find(h=>arr(h.occupants).includes(planet)),position=v259Position(e,planet),sign=v259Sign(e,planet,lang);
 const natalContext=natal?(ta?` பிறப்பு ஜாதகத்தில் இதே ${label} ${natal.house}-ஆம் பாவத்தில்${sign?' '+sign+' ராசியில்':''} இருக்கிறது. ஆகவே கோச்சாரத்தில் ${n}-ஆம் பாவம் இயக்கப்படும்போது பிறப்பில் உள்ள ${natal.house}-ஆம் பாவ அனுபவமும் இணையும்; இரண்டையும் ஒரே பாவமாகக் கருதக்கூடாது.`:` Natal ${planet} occupies house ${natal.house}${sign?' in '+sign:''}; its natal role qualifies this transit through house ${n}. The natal and transit houses must not be conflated.`):'';
 const owning=arr(position?.ownedHouses).filter(v259ValidHouse),lordText=owning.length?(ta?` ${label} ${owning.join(', ')}-ஆம் பாவங்களின் அதிபதியாகவும் குறிக்கப்பட்டுள்ளது; அந்தத் துறைகள் இங்கு கூடுதல் பின்னணி.`:` ${planet} is also recorded as ruler of house(s) ${owning.join(', ')}, adding those natal subjects to the context.`):'';
 const periods=arr(e?.dashas).filter(q=>q.start&&q.end&&z.start&&z.end&&q.start<=z.end&&q.end>=z.start),relevant=periods.find(q=>[q.md,q.ad].includes(planet));
 const timing=relevant?(ta?` ${relevant.start} → ${relevant.end} தசை/புக்தியில் ${label} நேரடியாக வருவதால் இந்தப் பார்வைக்கு இரண்டு தனித்த கால ஆதாரங்கள் உள்ளன; சம்பவம் உறுதி என்று பொருளல்ல.`:` ${planet} also appears as a dasha/bhukti ruler during ${relevant.start} → ${relevant.end}, adding a second timing indication without guaranteeing an outcome.`):(ta?' இந்தக் காலத்தில் அதே கிரகத்தின் தசை/புக்தி இணைப்பு கிடைக்கவில்லை; அதனால் கோச்சாரம் மட்டும் வைத்து குறிப்பிட்ட நிகழ்வைக் கூறுவதில்லை.':' No overlapping dasha/bhukti activation of this planet is supplied, so the transit alone does not justify a dated event.');
 return `${z.start} → ${z.end}: ${ta?`${label} ${n}-ஆம் பாவத்தில் செல்லும்போது ${meaning||'அப்பாவக் காரகங்கள்'} முன்னிலையாகலாம்.`:`${label} transiting house ${n} can emphasize ${meaning||'its house-related themes'}.`}${natalContext}${lordText}${timing}`;
}
function v253Profile(profile,lang,who){
 const ta=lang==='ta',out=[];
 for(const layer of arr(profile?.layers)){
 const facts=arr(layer.houses).filter(h=>h.lordHouse&&h.lord).map(h=>ta?`${h.house}-ஆம் பாவ அதிபதி ${v251Planet(h.lord,lang)}${Number.isInteger(h.lordSignIndex)?' '+V257_SIGNS.ta[h.lordSignIndex]+' ராசியில்':''} ${h.lordHouse}-ஆம் பாவத்தில்`:`house ${h.house} ruler ${v251Planet(h.lord,lang)}${Number.isInteger(h.lordSignIndex)?' in '+V257_SIGNS.en[h.lordSignIndex]:''}, house ${h.lordHouse}`);
 if(facts.length)out.push(`${who} · ${layer.division}: ${facts.join('; ')}.`);
 }
 return out;
}
function v259PersonTopic(profile,score,lang,who,topic){
 const ta=lang==='ta',lines=[],layers=arr(profile?.layers);
 for(const layer of layers){
  if(!['D1','D9'].includes(layer.division))continue;
  const facts=arr(layer.houses).filter(q=>v259ValidHouse(q.house)).slice(0,3).map(q=>{
   const ruler=text(q.lord),dest=v259ValidHouse(q.lordHouse)?Number(q.lordHouse):null,sign=Number.isInteger(q.lordSignIndex)&&q.lordSignIndex>=0&&q.lordSignIndex<=11?V257_SIGNS[lang][q.lordSignIndex]:'',occ=arr(q.occupants).filter(Boolean).slice(0,3).map(p=>v251Planet(p,lang));
   return ta?`${q.house}-ஆம் பாவம்: ${ruler?v251Planet(ruler,lang)+' அதிபதி':''}${dest?' '+dest+'-ஆம் பாவத்தில்':''}${sign?' ('+sign+')':''}${occ.length?'; அப்பாவத்தில் '+occ.join(', '):''}${!dest&&!occ.length?' — முழு இருப்பிடம் கிடைக்கவில்லை':''}`:`house ${q.house}: ${ruler?ruler+' as ruler':''}${dest?' in house '+dest:''}${sign?' ('+sign+')':''}${occ.length?'; occupied by '+occ.join(', '):''}${!dest&&!occ.length?' — placement incomplete':''}`;
  });
  if(facts.length)lines.push(ta?`${who} ${layer.division} ஆதாரம் (${topic}): ${facts.join('； ')}.`:`${who} ${layer.division} evidence (${topic}): ${facts.join('; ')}.`);
 }
 const enough=layers.some(l=>l.division==='D1'&&arr(l.houses).some(h=>v259ValidHouse(h.lordHouse)||arr(h.occupants).length));
 if(!enough)return [ta?`${who} — ${topic}: தீர்மானிக்கத் தேவையான D1 பாவ/அதிபதி நிலை முழுமையாக இல்லை; மதிப்பெண் மட்டும் வைத்து இயல்பை நிர்ணயிக்க இயலாது.`:`${who} — ${topic}: D1 ruler/occupation evidence is incomplete; a numerical score is not enough to infer this person's behaviour.`];
 const band=Number.isFinite(score)?score>=2.25?'support':score<=-1.5?'pressure':'mixed':'unknown';
 const judgment=ta?band==='support'?`இந்த ஆதாரங்களுக்கு அளிக்கப்பட்ட எடையில் ${topic} பகுதியில் உதவும் காரணிகள் அதிகம். அது தனிப்பட்ட குணத்தை உறுதி செய்யாது; தினசரி அனுபவத்துடன் ஒப்பிட வேண்டும்.`:band==='pressure'?`${topic} பகுதியில் தீர்க்கப்பட வேண்டிய சுமை காணப்படுகிறது. ஒருவரைக் குற்றம் கூறாமல் எந்தப் பாவத் தொடர்பு சிரமத்தை தருகிறது என்பதைச் சரிபார்க்க வேண்டும்.`:band==='unknown'?`${topic} குறித்த எடை கணக்கிடப்படவில்லை; ஊக முடிவு வழங்கவில்லை.`:`${topic} பகுதியில் ஆதரவும் அழுத்தமும் சேர்ந்து உள்ளன. D1 மற்றும் கிடைத்த D9 ஆதாரம் ஒத்திருக்கிறதா என்பதைப் பார்த்தே முடிவு கூற வேண்டும்.`:
 band==='support'?`The available weighting favours support for ${topic}, but does not establish this person's character; compare the indicators with lived behaviour.`:band==='pressure'?`Unresolved pressures occur around ${topic}. Examine which chart links are demanding without assigning blame to this person.`:band==='unknown'?`A score is unavailable; no outcome is inferred.`:`Support and pressure coexist in ${topic}; check the D1 indication against any reliable D9 evidence rather than labelling the person.`;
 return [...lines,judgment];
}
function v253MatchingTopic(t,lang,e){
 const ta=lang==='ta',old=topicText(t,lang,e),ageB=yearsAt(e?.brideBirthDate,e?.referenceDate),ageG=yearsAt(e?.groomBirthDate,e?.referenceDate);
 if(ageB!=null&&ageB<18||ageG!=null&&ageG<18)return old;
 const good=pickLang(t.supportReading,lang),care=pickLang(t.careReading,lang),state=t.state;
 const bs=t.brideScore==null?NaN:Number(t.brideScore),gs=t.groomScore==null?NaN:Number(t.groomScore),topic=ta?text(t.titleTa)||old.title:text(t.titleEn)||old.title;
 const b=v259PersonTopic(t.brideProfile,bs,lang,ta?'பெண்':'Bride',topic),g=v259PersonTopic(t.groomProfile,gs,lang,ta?'ஆண்':'Groom',topic);
 const difference=Number.isFinite(bs)&&Number.isFinite(gs)?Math.abs(bs-gs):null;
 const pair=state==='mutual'?(ta?`இரு ஜாதகங்களிலும் ${topic} சார்ந்த பாரம்பரிய ஆதரவு இருப்பதாக மதிப்பீடு கூறுகிறது. நடைமுறையில் இருவரும் ஒரே வேகத்தில் செயல்படுவார்கள் என்பதற்கு இது ஆதாரம் அல்ல.`:`Both charts are assessed as supportive around ${topic}, although this does not mean identical habits or readiness.`):state==='pressure'?(ta?`${topic} பகுதியில் இருவருக்குமான தீராத சுமை கணக்கில் வருகிறது. ஒரு தோஷத்தைக் காட்டி ஒருவரை மட்டுமே காரணமாகக் கூறாமல் இரு D1/D9 சுட்டிகளையும் பார்க்க வேண்டும்.`:`Both charts have unresolved pressures around ${topic}. Compare their respective D1/D9 indicators; do not attribute the issue to one partner.`):state==='asym'&&difference!=null?(ta?`${topic} பகுதியில் ${bs>gs?'பெண்':'ஆண்'} ஜாதகத்தின் மதிப்பீடு ஒப்பீட்டளவில் அதிகம் (${signed(bs)} / ${signed(gs)}). இது நல்லவர்/கெட்டவர் என்ற தரவரிசை அல்ல; எதிர்பார்ப்புகளின் வேகம் வேறுபடலாம் என்பதற்கான குறிப்பே.`:`The ${bs>gs?'bride':'groom'} assessment is comparatively higher for ${topic} (${signed(bs)} / ${signed(gs)}). This is not a ranking of the partners, but a prompt to compare different expectations.`):(ta?`${topic} பகுதியில் ஆதரவும் சிரமமும் இணைந்து இருப்பதாகக் கணக்கிடப்பட்டுள்ளது; இரு பக்க ஆதாரங்களையும் இணைத்தே இறுதி முடிவு கொள்ள வேண்டும்.`:`The calculation yields mixed indicators for ${topic}; both charts need to be weighed together.`);
 const reading=state==='pressure'?care:state==='mutual'?good:(good&&care?good+' '+care:good||care);
 // Preserve the original unique topic-level practical advice, without repeating a static bank of generic "human" paragraphs.
 const advice=old.paragraphs?.[1]||'',guidance=pickLang(t.guidance,lang);
 return {...old,title:topic,paragraphs:v253Unique([pair,...b,...g,reading,advice,guidance])};
}
function v253CleanReport(report){
 // Remove exact repeated paragraphs within a narrative, never calculation tables.
 for(const lang of ['en','ta']){const r=report[lang];if(!r)continue;const seen=new Set();const clean=a=>{if(!a?.paragraphs)return;const unique=ps=>v253Unique(ps).filter(p=>{const k=text(p).toLowerCase();if(seen.has(k))return false;seen.add(k);return true});if(a.sections){a.sections=a.sections.map(s=>({...s,paragraphs:unique(s.paragraphs)})).filter(s=>s.paragraphs.length);a.paragraphs=a.sections.flatMap(s=>s.paragraphs)}else a.paragraphs=unique(a.paragraphs)};
 for(const a of [...arr(r.life),...arr(r.timing?.phases),...arr(r.timing?.areas),...arr(r.topics)])clean(a);
 }
 return report;
}

if(typeof module!=='undefined'&&module.exports)module.exports={VERSION,synthesize};
else globalThis.SMVPredictionSynthesis={VERSION,synthesize};

